static char s[MAXN];
static int pos, len;

long long mod_pow2_div(long long x, long long y) {
    if (y >= 63) return 0;
    return x >> y;
}

long long parse_expr();

/* Skip spaces if any */
void skip_spaces() {
    while (pos < len && isspace((unsigned char)s[pos])) pos++;
}

/*
Assumed grammar (standard for this problem):
expr := number
      | 'S' '(' expr ')'
      | '(' expr '>>' expr ')'

All input expressions are valid.
*/

long long parse_number() {
    skip_spaces();
    long long v = 0;
    while (pos < len && isdigit((unsigned char)s[pos])) {
        v = v * 10 + (s[pos] - '0');
        pos++;
    }
    return v;
}

long long parse_expr() {
    skip_spaces();

    if (isdigit((unsigned char)s[pos])) {
        return parse_number();
    }

    if (s[pos] == 'S') {
        pos++; /* S */
        skip_spaces();
        if (s[pos] == '(') pos++;
        long long x = parse_expr();
        skip_spaces();
        if (s[pos] == ')') pos++;
        x %= MOD;
        return (x * x) % MOD;
    }

    if (s[pos] == '(') {
        pos++; /* ( */
        long long left = parse_expr();
        skip_spaces();
        /* consume >> */
        if (s[pos] == '>' && s[pos + 1] == '>') pos += 2;
        long long right = parse_expr();
        skip_spaces();
        if (s[pos] == ')') pos++;
        return mod_pow2_div(left, right);
    }

    return 0; /* valid input guarantees this won't matter */
}

