def parse_expression(s, i):
    # Parse a term possibly followed by '>>' and another term
    x, i = parse_term(s, i)
    while i < len(s) and s[i] == '>':
        # must be '>>'
        i += 2
        y, i = parse_term(s, i)
        x = x >> y  # floor division by 2**y
    return x, i

def parse_term(s, i):
    if s[i] == 'S':
        # S<expr>
        i += 1  # skip 'S'
        if s[i] == '(':
            i += 1  # skip '('
            x, i = parse_expression(s, i)
            i += 1  # skip ')'
        else:
            x, i = parse_expression(s, i)
        x = (x * x) % MOD
        return x, i
    else:
        return parse_number(s, i)

def parse_number(s, i):
    num = 0
    while i < len(s) and s[i].isdigit():
        num = num * 10 + (ord(s[i]) - 48)
        i += 1
    return num, i

def evaluate(expr):
