def tokenize(s):
    tokens = []
    i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1
        elif s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
        elif s[i] == 'S':
            tokens.append(('S', 'S'))
            i += 1
        elif s[i] == '>':
            if i+1 < len(s) and s[i+1] == '>':
                tokens.append(('SHIFT', '>>'))
                i += 2
            else:
                raise ValueError("Unknown token")
        elif s[i] == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif s[i] == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        else:
            raise ValueError(f"Unknown char {s[i]}")
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, typ=None):
        tok = self.tokens[self.pos]
        if typ and tok[0] != typ:
            raise ValueError(f"Expected {typ}, got {tok}")
        self.pos += 1
        return tok

    def parse_expr(self):
        left = self.parse_term()
        while self.peek() and self.peek()[0] == 'SHIFT':
            self.consume('SHIFT')
            right = self.parse_term()
            # left >> right = floor(left / 2^right)
            left = left >> right
        return left

    def parse_term(self):
        if self.peek() and self.peek()[0] == 'S':
            self.consume('S')
            self.consume('LPAREN')
            val = self.parse_expr()
            self.consume('RPAREN')
            return (val * val) % MOD
        else:
            return self.parse_factor()

    def parse_factor(self):
        if self.peek() and self.peek()[0] == 'NUM':
            tok = self.consume('NUM')
            return tok[1]
        elif self.peek() and self.peek()[0] == 'LPAREN':
            self.consume('LPAREN')
            val = self.parse_expr()
            self.consume('RPAREN')
            return val
        else:
            raise ValueError(f"Unexpected token {self.peek()}")

