using namespace std;

const long long MOD = 1000000007;

struct Token {
    enum Type { NUMBER, S_FUNC, SHIFT, LPAREN, RPAREN, END } type;
    long long value;
};

class Parser {
public:
    Parser(const string& s) : s(s), pos(0) {}

    long long parse() {
        next_token();
        long long result = expr();
        return result;
    }

private:
    string s;
    size_t pos;
    Token cur;

    void next_token() {
        while (pos < s.size() && isspace(s[pos])) pos++;
        if (pos >= s.size()) {
            cur.type = Token::END;
            return;
        }
        char c = s[pos];
        if (c == '(') { cur.type = Token::LPAREN; pos++; }
        else if (c == ')') { cur.type = Token::RPAREN; pos++; }
        else if (c == '>') {
            if (pos + 1 < s.size() && s[pos+1] == '>') {
                cur.type = Token::SHIFT;
                pos += 2;
            } else {
                // should not happen in valid input
                cur.type = Token::END;
            }
        }
        else if (c == 'S') {
            cur.type = Token::S_FUNC;
            pos++;
        }
        else if (isdigit(c)) {
            long long val = 0;
            while (pos < s.size() && isdigit(s[pos])) {
                val = val * 10 + (s[pos] - '0');
                pos++;
            }
            cur.type = Token::NUMBER;
            cur.value = val;
        }
        else {
            cur.type = Token::END; // error
        }
    }

    long long expr() {
        long long left = term();
        while (cur.type == Token::SHIFT) {
            next_token();
            long long right = term();
            // left >> right = floor(left / 2^right)
            left = left >> right;  // integer shift works since right is non-negative
        }
        return left;
    }

    long long term() {
        if (cur.type == Token::NUMBER) {
            long long val = cur.value;
            next_token();
            return val;
        }
        else if (cur.type == Token::S_FUNC) {
            next_token();
            if (cur.type == Token::LPAREN) {
                next_token();
                long long arg = expr();
                if (cur.type == Token::RPAREN) {
                    next_token();
                }
                return (arg * arg) % MOD;
            }
            // S without parentheses? specification says S<x> but BNF shows S(x)
            // fallback: treat next token as argument
            long long arg = term();
            return (arg * arg) % MOD;
        }
        else if (cur.type == Token::LPAREN) {
            next_token();
            long long val = expr();
            if (cur.type == Token::RPAREN) {
                next_token();
            }
            return val;
        }
        // error
        return 0;
    }
};

