static const long long MOD = 1000000007LL;

struct Parser {
    string s;
    int n, pos;

    Parser(const string& str) : s(str), n((int)str.size()), pos(0) {}

    void skipSpaces() {
        while (pos < n && isspace((unsigned char)s[pos])) pos++;
    }

    long long parseNumber() {
        skipSpaces();
        long long val = 0;
        while (pos < n && isdigit((unsigned char)s[pos])) {
            val = val * 10 + (s[pos] - '0');
            pos++;
        }
        return val;
    }

    // factor := number | 'S' '(' expr ')'
    long long parseFactor() {
        skipSpaces();
        if (pos < n && s[pos] == 'S') {
            pos++; // consume 'S'
            skipSpaces();
            if (pos < n && s[pos] == '(') pos++;
            long long x = parseExpr();
            skipSpaces();
            if (pos < n && s[pos] == ')') pos++;
            __int128 t = (__int128)(x % MOD) * (x % MOD);
            return (long long)(t % MOD);
        } else {
            return parseNumber();
        }
    }

    // expr := factor { ">>" factor }
    // left-associative
    long long parseExpr() {
        long long val = parseFactor();
        while (true) {
            skipSpaces();
            if (pos + 1 < n && s[pos] == '>' && s[pos + 1] == '>') {
                pos += 2;
                long long y = parseFactor();
                if (y >= 63) val = 0;
                else val = val >> y;
            } else {
                break;
            }
        }
        return val;
    }
};

